import{_ as r,a8 as l,o as n,c as s,ah as _,a as p,K as i,L as d,a3 as c}from"./chunks/framework.B6ehkn__.js";import"./chunks/theme.BfMjDZ3-.js";const v=JSON.parse('{"title":"灯光","description":"","frontmatter":{"tags":["home-design","life","lighting"],"abstract":"家居灯光设计要点——无主灯的流行与坑、高级光环境的三大要素（基础照明、重点照明、氛围照明）及反光灯槽、射灯等具体做法。","category":["🌱 生活"]},"headers":[],"relativePath":"vault/Knowledge/Life/房屋设计-灯光.md","filePath":"vault/Knowledge/Life/房屋设计-灯光.md","lastUpdated":1790655645000}'),h={name:"vault/Knowledge/Life/房屋设计-灯光.md"};function b(m,e,f,g,u,N){const a=l("VPNolebaseInlineLinkPreview"),o=l("NolebaseGitContributors"),t=l("NolebaseGitChangelog");return n(),s("div",null,[e[1]||(e[1]=_('<h1 id="灯光" tabindex="-1">灯光 <a class="header-anchor" href="#灯光" aria-label="Permalink to “灯光”">​</a></h1><h2 id="_1-灯光设计的坑" tabindex="-1">1 灯光设计的坑 <a class="header-anchor" href="#_1-灯光设计的坑" aria-label="Permalink to “1  灯光设计的坑”">​</a></h2><p>先说最火的：无主灯。 现在装修公司开口就推“无主灯”， 好像主灯已经落伍。 其实，有主灯、无主灯，没有绝对好坏， 只有适不适合。 无主灯为什么火？</p><ol><li>层高矮，去掉大吊灯，空间更利落。</li><li>智能联动，场景一键切换，看起来很酷。</li></ol><p>但坑也最多： 90% 的设计师只会“模板抄作业”—— 天花板上密密麻麻打满孔， 再小的客厅也要塞两条磁吸轨道， 结果钱花了，光却乱成“满天星”。</p><h2 id="_2-好的室内灯光设计是怎样的" tabindex="-1">2 好的室内灯光设计是怎样的 <a class="header-anchor" href="#_2-好的室内灯光设计是怎样的" aria-label="Permalink to “2  好的室内灯光设计是怎样的”">​</a></h2><p>核心：简洁、有明有暗、有立体感 高级光环境的三大要素：</p><ol><li>基础照明：告别“一盏主灯照亮全家”的误区。而是多用间接照明打造均匀柔和、模拟自然光的基础光环境。</li><li>重点照明：像舞台追光一样，聚焦你需要亮化的区域（如餐桌、装饰画），瞬间提升空间层次感。</li><li>氛围照明：别忽略用落地灯、壁灯等装饰性光源画龙点睛，营造你想要的情调和氛围。</li></ol><hr><ol><li><p>基础照明——“看得见”</p></li><li><p>目标：均匀、柔和、不刺眼。 别再用一盏吸顶灯怼满全屋。</p></li><li><p>推荐三种做法：</p><ol><li>反光灯槽 做吊顶：一圈回形顶里藏灯带，灯光打到天花再漫反射下来。 不吊顶：买免吊顶铝槽，贴墙走线，一样出效果。</li><li>线性灯 记得选“上发光”款，见光不见灯，才不会眩光。 需要提前预埋型材，适合自装或毛坯阶段。</li><li>筒灯/射灯 筒灯光散，容易晃眼，只适合走廊、过道。 射灯聚光，有防眩杯，角度可调， 开孔小、颜值高的“深杯射灯”是首选。</li></ol></li><li><p>重点照明——“看得爽”</p></li><li><p>舞台追光灯原理，把光精确打到你想炫耀的东西： 爷爷的字画、旅行的纪念品、厨房台面、餐桌、阅读角…… 没预留电位？ 选充电款、轨道款、甚至拉一条明线，都能补光。 色温可以比环境光暖一点，但别差太多，300K 以内。</p></li><li><p>氛围照明——“看得醉”</p></li><li><p>画龙点睛，靠装饰灯完成： 落地灯、壁灯、吊灯、床底悬浮灯带、窗帘盒灯带…… 既是光源，也是软装。 色温统一，整屋 2700-3500K 之间， 局部可以上下浮动 300K， 显色指数 Ra≥90， 灯具款式全屋不超过 3 种， 数量能少就少，别为了对称硬加。</p></li></ol><h2 id="_3-如何最方便快捷打造好的光环境" tabindex="-1">3 如何最方便快捷打造好的光环境 <a class="header-anchor" href="#_3-如何最方便快捷打造好的光环境" aria-label="Permalink to “3  如何最方便快捷打造好的光环境”">​</a></h2><p>一张清单照抄：</p><ol><li>基础照明别太亮，间接光优先。</li><li>重点照明给物件/操作区，记得防眩。</li><li>氛围照明做“最后一笔”，统一色温。</li><li>灯具款式≤3 种，数量越少越高级。</li><li>预算够，上智能开关，场景一键切换。</li></ol><p>参考来源：</p>',14)),p("p",null,[i(a,{href:"https://www.bilibili.com/video/BV1g6e8zMECV/?spm_id_from=333.1007.tianma.18-3-69.click&vd_source=ef07229398779363e8a56f68ad3b105e",target:"_blank",rel:"noreferrer"},{default:d(()=>[...e[0]||(e[0]=[c("掌握灯光基本技巧，老破小也能装出高级效果_哔哩哔哩_bilibili",-1)])]),_:1})]),i(o),i(t)])}const V=r(h,[["render",b]]);export{v as __pageData,V as default};
